// ---------------- SPEECH SETUP ----------------
$scope.recordingState = {};
var recognition;
var activeField = null; 
var isFirstRecognitionChunk = true;
var recognitionIsListening = false;
var pendingRecognitionStart = null;
var recognitionStartAttempts = 0;
var pendingRecordingField = null;

function clearPendingRecognitionStart() {
	if (pendingRecognitionStart) {
		clearTimeout(pendingRecognitionStart);
		pendingRecognitionStart = null;
	}
}

function broadcastStopCoversheetSpeech(source) {
	$rootScope.$broadcast('coversheetSpeech:stop', source || 'ipd');
}

function beginRecording(fieldKey) {
	if (activeField === fieldKey) {
		stopAllRecordings();
		return;
	}
	stopAllRecordings();
	broadcastStopCoversheetSpeech('ipd');
	activeField = fieldKey;
	pendingRecordingField = fieldKey;
	isFirstRecognitionChunk = true;
	startRecognition();
}

function startRecognition(delay) {
	if (!recognition || !activeField || recognitionIsListening || pendingRecognitionStart) return;

	if (delay) {
		pendingRecognitionStart = setTimeout(function () {
			pendingRecognitionStart = null;
			startRecognition(0);
		}, delay);
		return;
	}

	try {
		recognition.start();
	} catch (e) {
		if (activeField && recognitionStartAttempts < 6) {
			recognitionStartAttempts++;
			startRecognition(250);
			return;
		}
		stopAllRecordings();
		$scope.$applyAsync();
	}
}

function stopRecognition() {
	clearPendingRecognitionStart();
	recognitionIsListening = false;
	recognitionStartAttempts = 0;
	try {
		if (recognition) recognition.stop();
	} catch (e) {}
}

$scope.initSpeechRecognition = function () {

    if (!('webkitSpeechRecognition' in window || 'SpeechRecognition' in window)) {
        alert("Speech Recognition not supported");
        return;
    }

    var SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    recognition = new SpeechRecognition();

    recognition.lang = 'en-IN';
    recognition.continuous = true;
    recognition.interimResults = false;

	recognition.onstart = function () {
		recognitionIsListening = true;
		recognitionStartAttempts = 0;
		if (pendingRecordingField) {
			$scope.recordingState[pendingRecordingField] = true;
			pendingRecordingField = null;
			$scope.$applyAsync();
		}
	};

    recognition.onresult = function (event) {
        var transcript = '';

        for (var i = event.resultIndex; i < event.results.length; i++) {
            if (event.results[i].isFinal) {
                transcript += event.results[i][0].transcript;
            }
        }

        if (!transcript) return;

        if (isFirstRecognitionChunk) {
            transcript = transcript.charAt(0).toUpperCase() + transcript.slice(1);
            isFirstRecognitionChunk = false;
        }

        if (activeField === 'general') {
            $scope.descriptiveExamination =
                ($scope.descriptiveExamination || '') + transcript + ' ';
        }

        if (activeField === 'systemic') {
            $scope.sysDescriptiveExamination =
                ($scope.sysDescriptiveExamination || '') + transcript + ' ';
        }

        if (activeField === 'physician') {
            $scope.observationObj.observationDesc =
                ($scope.observationObj.observationDesc || '') + transcript + ' ';
        }

        if (activeField === 'nurseN') {
            $scope.nursingNoteObj.template =
                ($scope.nursingNoteObj.template || '') + transcript + ' ';
        }

        if (activeField === 'complaintN') {		
            $scope.dataComplObj.remark =
                ($scope.dataComplObj.remark || '') + transcript + ' ';
        }

        if (activeField === 'vaccinationN') {		
            $scope.vaccinationNote =
                ($scope.vaccinationNote|| '') + transcript + ' ';
        }

        if (activeField === 'advicedInstruction') {		
            $scope.advicedInstruction =
              
			($scope.advicedInstruction|| '') + transcript + ' ';
        }
        if (activeField === 'vaccinationChat') {		
            $scope.vaccinationNote =
                ($scope.vaccinationNote|| '') + transcript + ' ';
        }


        $scope.$applyAsync();
    };

    recognition.onend = function () {
		recognitionIsListening = false;
        if (activeField && $scope.recordingState[activeField]) {
			startRecognition();
        }
    };

    recognition.onerror = function (e) {
        console.error("Speech error:", e);
		stopAllRecordings();
		$scope.$applyAsync();
    };
};

