							$scope.getSpecialityList = function() {
								var URI = BASE_URL + ROOT_URL
										+ GETACTIVESPECIALITY;
								BillingGenericService
										.serviceAction(METHOD_POST, URI,
												commonObj,
												NOTIFICATION_MSG_STATUS_FALSE)
										.then(
												function(response) {
													if (response.data.status == "success")
														$scope.specialityList = response.data.listObject;
													angular.forEach($scope.specialityList, function(value,index){
														if(value.specialityId == $stateParams.patientDetailsObj.specialityId){
															/*
															 * var obj={
															 * "specialityName":value.specialityName,
															 * "specialityId":value.specialityId }
															 * $scope.specialityList.push(obj);
															 */
															$scope.medicationSpecialityId=$stateParams.patientDetailsObj.specialityId.toString();
															$scope.medicationDoctorId=$stateParams.patientDetailsObj.doctorId.toString();
														}
													});
												});
							}
							$scope.getSpecialityList();

