                              $scope.getOrderset = function(diagnosisId,orderSetMainActiveTab) {
                                     $rootScope.startLoader();
                                     $scope.orderSetMainActiveTab = orderSetMainActiveTab;
                                     var URI = BASE_URL + ROOT_URL + "/api/orderset/orderSetsDetails";
                                     var param = {
                                          orgId:$scope.organizationId,
                                          unitId:$scope.unitId,
                                          ordersetMasterId:0,
                                          diagnosisId:(orderSetMainActiveTab == 1) ? diagnosisId : null,
                                          icpcId:      (orderSetMainActiveTab == 1) ? null : diagnosisId,
                                          doctorId:$scope.doctorId,
                                          specialityId : $stateParams.patientDetailsObj.specialityId,
                                          orderSetActiveTab:orderSetMainActiveTab
                                     };
                                     BillingGenericService.serviceAction("POST", URI, param).then(function(response)
                                     {
                                        if(response.data.status == "success"){
                                             $scope.orderSetObjList = response.data.listObject || [];
                                             if($scope.orderSetObjList.length != 0){
                                                 console.log("orderSetObjList JSON:",JSON.stringify($scope.orderSetObjList, null, 2));
                                                    angular.forEach($scope.orderSetObjList, function (obj) {
                                                        obj.activeTab = 1;
                                                    });
                                                    $("#ordersetDetailsModal").modal({
                                                        backdrop: 'static',
                                                        keyboard: false
                                                    });
                                             }
                                             else if ($scope.actulSaveComplaintFromFavFlag==true){
                                                  var dData = {
                                                         complaintAdmissionId : '0',
                                                         diagnosisId : $scope.icpcIdCodeFromFav,
                                                         diagnosisName : $scope.icpcDescFromFav,
                                                         duration : 'Day',
                                                         icpcCodeText : '',
                                                         since : '',
                                                         remark : '',
                                                         isReviewedFlag : 'N',
                                                         nos : 'N',
                                                         icpcSystemId : $scope.icpcSystemIdFromFav
                                                  }
                                               $scope.dataListComplaints = [ dData ];
                                               $scope.saveComplaints();
                                             }else{
                                                growl.warning( "No order set mapped..!", {
                                                    title : 'Warning!'
                                                });
                                                return;
                                              }
                                              $rootScope.stopLoader();
                                            }
                                        else if(response.data.status == "error")
                                            {
                                             $rootScope.stopLoader();
                                            }
                                    });
                              }
							
							
							$scope.addDuplicateSerives =function()
							{
								$scope.addedServiceOrdersForDisplay = $scope.addedServiceOrdersForDisplay.concat($scope.dublicateSerivceList);
								$scope.totalServiceAmount = 0;
								  angular.forEach($scope.addedServiceOrdersForDisplay,function(value,key){
									  $scope.totalServiceAmount += value.finalPrice;
								  });
							}
							$scope.totalOrderSetids = [];
							$scope.fromOrderSetServices = false;
							$scope.addSelectedOrderSet = false;
							$scope.addSelectedOrderSetAdd = function(index)
							{
								if ($scope.selectedOrderSet.length == 0) {
									growl.warning("Please select Order set..!", {
										title : 'Warning!'
									});
									return;
								}
								else{ 
									$scope.addSelectedOrderSet = true;
									 $scope.dataListDiagnosis[index].selectedOrderSet = $scope.selectedOrderSet;
								    }
							}
							
							
