							$scope.getsurgicalCalenderData = function(fromDate,
									toDate) {
								$rootScope.startLoader();
								var fromDate1 = fromDate == undefined ? new Date()
										: fromDate;
								var fromDate = moment(fromDate1)
										.startOf('week').add('day', 1).format(
												'YYYY-MM-DD');
								var toDate = moment(fromDate1).endOf('week')
										.add('day', 1).format('YYYY-MM-DD');
								$scope.datepickerSurFrom = moment(fromDate1)
										.startOf('week').add('day', 1).toDate();
								$scope.datepickerSurgicalTo = moment(fromDate1)
										.endOf('week').add('day', 1).toDate();

								var data = {
									orgId : $scope.organizationId,
									unitId : $scope.unitId,
									doctorId : $stateParams.patientDetailsObj.doctorId,
									fromDate : fromDate,
									toDate : toDate,
									status : 'A'
								}

								console.log("data", data);
								$scope.surgicalCalenderList = [];

								var URI = BASE_URL + ROOT_URL
										+ "/api/otims/surgicalCalender/weekly";
								BillingGenericService
										.serviceAction(METHOD_POST, URI, data,
												NOTIFICATION_MSG_STATUS_FALSE)
										.then(
												function(response) {
													if (response.data.status == 'success') {
														$rootScope.stopLoader();
														$scope.surgicalCalenderList = response.data.listObject;
														$scope.listCount = response.data.object == 0 ? 8
																: response.data.object;
														if ($scope.procedureOrderList.length > 0
																&& $scope.surgicalCalenderList != null) {
															var i = 0;
															angular
																	.forEach(
																			$scope.surgicalCalenderList,
																			function(
																					value,
																					key) {

																				angular
																						.forEach(
																								$scope.procedureOrderList,
																								function(
																										value1,
																										key) {
																									angular
																											.forEach(
																													$scope.surgicalCalenderList[i].surgicalCalendarDetailsDtoList,
																													function(
																															value2,
																															key) {
																														angular
																																.forEach(
																																		value1.listCalenderMapperDto,
																																		function(
																																				value3,
																																				key) {
																																			if (value2.surgicalCalenderId == value3.surgicalCalenderId) {
																																				value2.calenderStatusId = 2;
																																			}

																																		});
																													});
																								});
																				i++;
																			});
														}

														$(
																'#surgicalCalendar-ipd-Modal')
																.modal('show');
													} else if (response.data.error == 'error') {
														$rootScope.stopLoader();
														$(
																'#surgicalCalendar-ipd-Modal')
																.modal('show');
													}

												});

							}
							
							$scope.procedureDt = ''; 
							$scope.showCalender = function() {
								if ($scope.procedureDate == undefined) {
									growl.warning(
											"Please select Procedure Date.", {
												title : 'Warning!'
											});
									return false;
								} else {
									var arr = $scope.procedureDate.split(" ");
									$scope.newDate = arr[0];
									$scope.procedureDt = $scope.newDate.split('-');
									var year1  = $scope.procedureDt[2];
									var month1 = $scope.procedureDt[1];
									var day1 = $scope.procedureDt[0];
									var procDate = year1+"-"+month1+"-"+day1;
									var procedureWeek = moment(
											procDate).add('day', 2)
											.toDate();
									var pWeekDate = moment(procedureWeek)
											.startOf('week').add('day', 1)
											.toDate();
									$scope.getsurgicalCalenderData(pWeekDate,
											undefined);
								}
							}

