							$scope.bookSlot = function(weekDate, weeMstIndex,
									slotIndex) {
								var procDate = $scope.procedureDt;
								var weekDte = moment(weekDate).format(
										'DD-MM-YYYY');
								var array = $scope.procedureDate.split('-');
								var newDate = "";
								var yearSpit =array[2].split(' ');
							     newDate = array[0]+'-'+array[1]+'-'+yearSpit[0];

								var todayDate = moment().format('DD-MM-YYYY');
								if (weekDte == procDate && weekDte >= todayDate) {
									var slotsIDX = [];
									$scope.calandarSlotMpprList = [];
									var duration = $scope.procedureDuration / 30;
									var noOfSlots = Math.ceil(duration);
									var slotMppr1 = angular
											.copy($scope.calandarSlotMppr);
									$scope.surgicalCalenderList[weeMstIndex].surgicalCalendarDetailsDtoList[slotIndex].calenderStatusId = 2;
									slotsIDX.push(slotIndex);
									slotMppr1.surgicalCalenderId = $scope.surgicalCalenderList[weeMstIndex].surgicalCalendarDetailsDtoList[slotIndex].surgicalCalenderId;
									$scope.calandarSlotMpprList.push(slotMppr1);
									var j = 1;
									for (var i = noOfSlots - 1; i > 0; i--) {
										if ($scope.surgicalCalenderList[weeMstIndex].surgicalCalendarDetailsDtoList[slotIndex
												+ j].calenderStatusId == 1) {
											$scope.surgicalCalenderList[weeMstIndex].surgicalCalendarDetailsDtoList[slotIndex
													+ j].calenderStatusId = 2;
											slotsIDX.push(slotIndex + j);
											var slotMppr = angular
													.copy($scope.calandarSlotMppr);
											slotMppr.surgicalCalenderId = $scope.surgicalCalenderList[weeMstIndex].surgicalCalendarDetailsDtoList[slotIndex
													+ j].surgicalCalenderId;
											$scope.calandarSlotMpprList
													.push(slotMppr);
											j++;
										} else {
											$scope.calandarSlotMpprList = [];
											for (var p = 0; p < slotsIDX.length; p++) {
												$scope.surgicalCalenderList[weeMstIndex].surgicalCalendarDetailsDtoList[slotsIDX[p]].calenderStatusId = 1;
											}
											alert("Time exceeds");
											return false;
										}
									}
								} 
							  if (newDate!=weekDte){
									growl
									.warning(
											"Procedure Date not be matched.",
											{
												title : 'Warning!'
											});
								}
								else {
									growl
											.warning(
													"Procedure Time not be matched.",
													{
														title : 'Warning!'
													});
								}

							}
