	                    							 $scope.validateAssessmentStartTime=function(){
	                    								 var cur = moment().format("HH:mm");
	                    									if( $scope.assessmentStartTime < $scope.checkInTime )
	                    										{
	                    											 growl.warning("Time cannot less than check in time.",
	                    														{
	                    															title : 'Warning!'
	                    														});
	                    												$scope.assessmentStartTime = $scope.checkInTime;
	                    												return false;
	                    										}else if($scope.assessmentStartTime > cur){
	                    											growl.warning("Time Should be less than current in time.",
	                    													{
	                    														title : 'Warning!'
	                    													});
	                    											$scope.assessmentStartTime = moment().format("HH:mm");
	                    											return false;
	                    										}
	                    									else{
	                    										 $scope.assessmentStartTime = $scope.assessmentStartTime;
	                    									   }
	                    							    	}
	                    							 
	                    							
	                                                $scope.validateAssessmentEndTime=function(){
	                                                	$scope.currentTimeInitial = moment().format("HH:mm");
	                                                	
	                    							if( ($scope.assessmentEndTime < $scope.assessmentStartTime) || ($scope.assessmentEndTime > $scope.currentTimeInitial))
	                    								{
	                    									 growl.warning(" End time should be greater than the start time and equal to or less than the current time. ",
	                    												{
	                    													title : 'Warning!'
	                    												});
	                    									 if($scope.assessmentEndTime > $scope.currentTimeInitial){
	                    									    $scope.assessmentEndTime = moment().format("HH:mm");	 
	                    									  }
	                    									 else if($scope.assessmentEndTime < $scope.assessmentStartTime){
	                    										$scope.assessmentEndTime = $scope.assessmentStartTime;
	                    									 }
	                    										return false;
//	                    								   
	                    								}
	                    							else{
	                    								 $scope.assessmentEndTime=$scope.assessmentEndTime;
	                    							   }
	                    					    	}
	                    					
