	                    							// save nursing assessment
													// critical
	                    							
	                    							$scope.saveNursingAssCritical = function()
	                    					       	{
	                    					       		var data = {
	                    					       			    encounterId: $scope.encounterDetailsObj.encounterId,
	                    										organizationId : $scope.organizationId,
	                    										unitId : $scope.unitId,
	                                                            isCritical : $scope.isCriticalObj.isCritical

	                    									}
	                    									var URI = BASE_URL + ROOT_URL+ MARKASCRITICAL;

	                    					       		GenericService.serviceAction(METHOD_POST,URI, data).then(function(response) {
	                    														if (response.data.status == "success")
	                    															{
	                                                                                $scope.isCritical =$scope.isCriticalObj.isCritical

	                    															}
	                    													});
	                    					       	}
	                    							
	                    							// save initial assessment
													// vitals
	                    							
	                    							$scope.saveInitialAssessmentVitals = function(vitalList){
	                    								var currtimePost = moment().format("HH:mm");
	                    								var paramObj = {};
	                    								var headers={
//	                    										'organization_id': $scope.organizationId,
//	                    										'unit_id':$scope.unitId,
	                    										'Content-Type':'application/json'
	                    								};
	                    								$scope.counter = 0;
	                    								  var data = {
	                    										 patientId : $scope.patientDetails.patientId,
	                    										 admissionId : $scope.patientDetails.admissionId,
	                    	                         		 	roleId : $scope.roleId,
	                    	                         		 	createdDate:moment(new Date()).format('DD-MM-YYYY HH:mm:ss'),
	                    										updatedDate:moment(new Date()).format('DD-MM-YYYY HH:mm:ss'),
	                    										updatedBy:$scope.userId,
	                    										createdBy:$scope.userId,
	                    										status:'A',
	                    										isEnteredInError:'N',
	                    										isPostFacto:$scope.isPostFacto,
	                    		                                postFactoDate:moment($scope.postFactoDate).format('DD-MM-YYYY HH:mm:ss'),
	                    		                                postFactoTime:$scope.postFactoTime!="" ? $scope.postFactoTime+":00" :currtimePost,
	                    										listAppointmentVitalMapperDtos : vitalList
	                    								  }
	                    								  console.log("Final Vital Save Arr",data);
	                    								
	                    								 // return false;
	                    								  var URI = BASE_URL + ROOT_URL+ SAVEAPPOINTMENTVITALMAPPER + "/"+ $scope.unitId +"/" + $scope.organizationId;
	                    							
	                    									GenericServiceParamHeader.serviceAction(METHOD_POST, URI,
	                    											data,
	                    											false,paramObj,headers)
	                    									.then(
	                    											function(response) {
	                    												console.log(response);
	                    												if (response.data.status == "success")
	                    													{
	                    														var keepGoing = true;
	                    														  angular.forEach($scope.vitalFinalList, function(value, key) {
	                    															  if(keepGoing) {
	                    																    if(value.vitalId == 3){
	                    																    	
	                    																    	 if(parseInt(value.vitalValue)>=250){
	                    																    		 $scope.isCriticalObj.isCritical='Y';
	                    																			  $scope.saveNursingAssCritical();
	                    																    		  keepGoing = false;
	                    																    	 }
	                    																    		 
	                    																    }else if(value.vitalId==7){
	                    																    	if(parseInt(value.vitalValue)<=50){
	                    																    		
	                    																    		$scope.isCriticalObj.isCritical='Y';
	                    																			  $scope.saveNursingAssCritical();
	                    																    		  keepGoing = false;
	                    																    	}
	                    																    	
	                    																    }else if(value.vitalId==4){
	                    																    		if(parseInt(value.vitalValue)>=150 || parseInt(value.vitalValue)<=50 ){
	                    																    			$scope.isCriticalObj.isCritical='Y';
	                    																				  $scope.saveNursingAssCritical();
	                    																	    		  keepGoing = false;
	                    																    		}
	                    																    	}
	                    																    }
	                    						                                });
	                    														  $scope.isPostFacto='N';
	                    									                         $scope.postFactoTime='';
	                    									                         $scope.postFactoDate='';
	                    														  var datalistVital = $scope.vitalFinalList;
	                    															for (var i = 0; i < datalistVital.length; i++) {
	                    																$scope.vitalFinalList[i].vitalValue = '';
	                    															}
	                    														  $rootScope.stopLoader();
	                    													}
	                    											});
	                    							
	                    							}
	                    							
