		$scope.setFirstTabLevel = function(newTab) {
			stopAllRecordings();
			$scope.setFirstLevelTab(newTab);
			$scope.firstTabLevel = newTab;
			if (newTab == '2') {
				$scope.setSecondTabLevel(5);
			}
			if (newTab == '4') {
				$scope.setAllergyDetails();
			}
			if (newTab == '3') {
				$scope.setHabitDetails();
			}
			if (newTab == '10') {
// $scope.setComplaintsDetails();
				$scope.getActiveComplaintlist();
			}
			if(newTab == '5'){
				$scope.setThirdTabLevel(1);
				$scope.setForthTabLevel(11);
				}
			if (newTab == '8') {
				$scope.getLastEncounterDetails();
			}
			if(newTab == '6'){
				$scope.skipReadyForBillingFlag = false;
				if ($scope.patientDetails.isFinalBill == 'Y') {
					$scope.skipReadyForBillingFlag = true;
              	  growl.warning(
								"You can not advice the services or medication for this patient as Final Bill has been already generated",
								{
									title : 'Warning!'
								}); 
               /*
				 * if($scope.skipReadyForBilling == 'N'){
				 * $scope.skipReadyForBillingFlag = true; growl.warning( "You
				 * can not advice for this patient as patient is now ready for
				 * billing...!!", { title : 'Warning!' }); }else{
				 * $scope.skipReadyForBillingFlag = true; growl.warning( "You
				 * can not advice for this patient as patient is
				 * discharged...!!", { title : 'Warning!' }); }
				 */
					
				}else{
					$scope.getPatientDiagnosis();
				}
				}
			if (newTab == '9') {
				$scope.skipReadyForBillingFlag = false;
				if ($scope.patientDetails.isFinalBill == 'Y') {
					$scope.skipReadyForBillingFlag = true;
              	  growl.warning(
								"You can not advice the services or medication for this patient as Final Bill has been already generated",
								{
									title : 'Warning!'
								}); 
               /*
				 * if($scope.skipReadyForBilling == 'N'){
				 * $scope.skipReadyForBillingFlag = true; growl.warning( "You
				 * can not advice for this patient as patient is now ready for
				 * billing...!!", { title : 'Warning!' }); }else{
				 * $scope.skipReadyForBillingFlag = true; growl.warning( "You
				 * can not advice for this patient as patient is
				 * discharged...!!", { title : 'Warning!' }); }
				 */
					
				}else{

					$scope.setSecondTabLevel(1);
				}

			}

			if (newTab == '1') {
                $rootScope.startLoader();
				$scope.dateList = [];
				$scope.dateListCopy=[];
                $scope.dateListCopyOfDates = [];

				$scope.progressNoteData();
				$timeout(function () {
// $rootScope.startLoader();
                    $scope.getUniqueDateList();
                }, 5000);
			}
			if (newTab == '11') {
				 $scope.getPatientSelfTriage(1);
					}
			if(newTab == '20'){
				$scope.getNursingNoteList();
			}
			if (newTab == '21') {
				$scope.isSetFirstTabLevel(21)
			}
		};
