		$scope.getButtonMaster =function(){
     	   var data = {};
     	   data.hospitalId=$scope.organizationId;
    		data.unitId=$scope.unitId;
			var URI = BASE_URL + ROOT_URL+"/api/global/getActiveButtonMaster";
			GenericService.serviceAction("POST", URI, data).then(
					function(response) {
						console.log(response.data);
						$scope.buttonData=response.data.listObject;
						$scope.AIButtonData=response.data.listObject2;
						$scope.disclaimer=response.data.object;
						$scope.data={};
						$scope.dynamicButtons = $scope.buttonData.filter(function(item) {
							$scope.data[item.tabId] = item.label;
							return item.tabId>43;
//				            return (item.tabId != 18 && item.tabId != 12 && item.tabId != 1 && item.tabId != 15
//				            && item.tabId != 14 && item.tabId != 20 && item.tabId != 13 && item.tabId != 31);  // Replace with your condition

				        });
						angular.forEach($scope.buttonData,function(val, index){
         				 if(val.tabId==1)
         					 {
         					$scope.smartMedication=val.label;
         					$scope.smartHeader=val.label;
         					 }
         				 if(val.tabId==2)
     					 {
     					$scope.smartDiagnostic=val.label;
     					$scope.smartHeader=val.label;
     					 }
         				 if(val.tabId==3)
     					 {
     					$scope.smartProcedure=val.label;
     					$scope.smartHeader=val.label;
     					 }
         				 if(val.tabId==4)
     					 {
     					$scope.smartConsultation=val.label;
     					$scope.smartHeader=val.label;
     					 }
         				 if(val.tabId==6)
     					 {
     					$scope.smartHistory=val.label;
     					$scope.smartHeader=val.label;
     					 }
         				 if(val.tabId==7)
     					 {
     					$scope.smartDrug=val.label;
     					$scope.smartHeader=val.label;
     					 }
         				 if(val.tabId==8)
     					 {
     					$scope.smartDiagnosis=val.label;
     					$scope.smartHeader=val.label;
     					 }
         				 if(val.tabId==9)
     					 {
     					$scope.smartExamination=val.label;
     					$scope.smartHeader=val.label;
     					 }
    					});
					});
        }
		 $scope.getButtonMaster();
