		$scope.getAISummaryData = function(){

            var data = {
                "patientId"      : $scope.patientDetails.patientId,
                "unitId"         : $scope.unitId,
                "organizationId" : $scope.organizationId,
            };

            var URI = BASE_URL + ROOT_URL +  "/api/ipd/getAISummaryData";;

            BillingGenericService
                .serviceAction(METHOD_POST, URI, data, NOTIFICATION_MSG_STATUS_FALSE)
                .then(function(response) {

                    $scope.aiSummaryData = [];

                    if (response.data.status == "success") {
                        if(response.data.listObject.length >0){
                            $scope.reportUrlList.push(response.data.listObject[0].documentPath);

                            return $scope.reportUrlList;
                        }

                    } else if (response.data.status == "error") {
                        console.log("Error  ")
                    }

                });
        };
 $scope.generateCaseSheetText = function () {
     let formattedText = '';
     $('#preprequirements_0').find('.heading-div').each(function () {
         let sectionName = $(this).text().replace(/\s+/g, ' ').trim();
         if (!sectionName) return;
         formattedText += sectionName + ':\n';
         let hasData = false;
         let content = $(this).parent().nextUntil(':has(.heading-div)');
         content.each(function () {
             let text = $(this).text().replace(/\s+/g, ' ').trim();
             if (text) {
                 hasData = true;
                 let lines = text.split('\n');
                 lines.forEach(function (line) {
                     let cleanLine = line.replace(/\s+/g, ' ').trim();
                     if (cleanLine) {
                         formattedText += '- ' + cleanLine + '\n';
                     }
                 });
             }
         });
         if (!hasData) {
             formattedText += '';
         }
         formattedText += '\n';
     });
     return formattedText.trim();
 };

