	        $scope.saveLetterOfAppointment=function(){
	        	if($scope.isAttachedToCoversheet==true)
	        		{
//	        		$scope.saveAndAttach()
	        		}
	        	var aiLetterData=null;
	        	 var aiLetterData = document.getElementById('letterTemplateBody').innerHTML;
	        	 $rootScope.startLoader();
	        	var data={};
	        	data.letterId=7;
	        	data.appointmentId= $stateParams.patientDetailsObj.admissionId;
	        	data.patientId=$stateParams.patientDetailsObj.patientId;
	        	data.aiLetter= aiLetterData;
	        	data.tabId=$scope.tabId;
	        	data.isSendTomail =true;
	        	data.organizationId = $scope.organizationId,
	        	data.unitId = $scope.unitId
	        	var URI = BASE_URL + ROOT_URL+"/api/global/saveLetterAttachment";
	        	GenericService.serviceAction("POST", URI, data).then(
	        			function(response) {
	        				if (response.data.status == "success") {
	        					growl.success("Response saved successfully");
	        					$rootScope.stopLoader();
	        				}
	        				else {
	        					$rootScope.stopLoader();
	        				}
	        			});

	        	var allowedTabs = [28, 29, 33, 34,43];
                if (allowedTabs.indexOf($scope.tabId) === -1) {
                    return;
                }
                var editorText = document.getElementById('letterTemplateBody').innerText.trim();
				var generalOldData = ($scope.descriptiveExamination || '').trim();
				var systemicOldData = ($scope.sysDescriptiveExamination || '').trim();
                switch ($scope.tabId) {

                    case 33: // General Examination
					if (!generalOldData) {
						$scope.descriptiveExamination = editorText;
					}
					else if (!generalOldData.includes(editorText)) {
						$scope.descriptiveExamination =
							generalOldData + '\n' + editorText;
					}

                        $scope.validateexamGen = true;
                        $scope.popUpFlag = false;
                        $scope.saveGeneralExamination(1);
                        break;

                    case 34: // Systemic Examination
					if (!systemicOldData) {
						$scope.sysDescriptiveExamination = editorText;
					}
					else if (!systemicOldData.includes(editorText)) {
						$scope.sysDescriptiveExamination =
						systemicOldData + '\n' + editorText;
					}

                        $scope.validateexamSys = true;
                        $scope.popUpFlag = false;
                        $scope.saveGeneralExamination(2);
                        break;

                    case 29: // Nursing Note
                        $scope.nursingNoteObj.nursingNoteDesc = "AI Generated Note";
                        $scope.nursingNoteObj.template = editorText;
                        $scope.saveNursingNote();
                        break;

                    case 28: // Physicain Note
                        $scope.observationObj.observationDesc = editorText;
                        $scope.saveObservation();
                        break;
                    case 43: // Order Set Print
                         var headerSize = "25px;";
                         var letterImgAndHeader = $scope.smartHeader;
                         var completeTemplateContent = document.getElementById('letterTemplateBody').innerHTML;

                         var printWindow = window.open('SmartOrderSet.html', 'SmartOrderSet', 'height=500,width=700');
                         printWindow.document.write('<html><head><title>SmartOrderSet</title></head>');
                         printWindow.document.write(' <style> '
                               + '.page-header, .page-header-space {height: '+headerSize+'} '
                               + ' .page-footer, .page-footer-space { height: 105px;} '
                               + ' .page-footer { position: fixed; bottom: 0; width: 100%;} '
                               + ' .page-header { position: fixed; top: 0mm; width: 100%;} '
                               + ' .page {page-break-after: auto;} '
                               + 'p { margin:0px 0px 0px 0px; }'
                               + '  @page { margin: 20mm}'
                               + ' </style>' );
                         printWindow.document.write('<body>');
                         printWindow.document.write(  '<div class="page-header" '
                               +  'style="text-align:center; font-size:22px; font-weight:bold; line-height:1.3;">'
                                 );
                         printWindow.document.write(letterImgAndHeader);
                         printWindow.document.write('</div>');
                         printWindow.document.write('<div class="page-footer" style="text-align: center">');
                         printWindow.document.write('</div>');
                         printWindow.document.write('<table> <thead> <tr><td><div class="page-header-space"></div> </td></tr> </thead>');
                         printWindow.document.write(' <tbody><tr><td><div class="page" style="line-height: 1.2;">');
                         printWindow.document.write(completeTemplateContent);
                         printWindow.document.write('</div> </td></tr></tbody>');
                         printWindow.document.write(' <tfoot> <tr><td><div class="page-footer-space"></div></td></tr></tfoot></table>');
                         printWindow.document.write('</body>');
                         printWindow.document.write('</html>');
                         printWindow.document.close();
                         $timeout( function(){
                            printWindow.print();
                         },2000);
                         break;
                }
                $('#letterTemplateModal').modal('hide');
	        }
