             $scope.addNewFavouriteMedication = function(){

                if(($scope.doctorFavoriteId === undefined || $scope.doctorFavoriteId === null || isNaN($scope.doctorFavoriteId))){
                    $scope.doctorFavoriteId ="";
                    return false;
                }
                console.log($scope.doctorFavoriteId);
                var itemObj = {};
                itemObj =  $scope.favouriteMedicationsFromMaster.find(function(item) {
                    return item.doctorFavoriteId === $scope.doctorFavoriteId;
                });

                $scope.updateFlag = false;
                $scope.updateFlagValidation = false;
                $scope.saveFlag = true;
                $scope.saveBtnFlag = true;
                $scope.updateScope = false;
                $scope.updateBtnFlag = false;
                $scope.itemSelectedList = {};
                $scope.itemSelectedList.items = [];

                $scope.itemSelectedList.items.push(itemObj);
                $scope.addFavouriteMedication();
                $scope.doctorFavoriteId = '';
             }

            $scope.getDoctorFavouriteMedicationList = function() {

                $rootScope.startLoader();
                var data = {
                    specialityId : $stateParams.patientDetailsObj.specialityId,
                    doctorId : $stateParams.patientDetailsObj.doctorId,
                    organizationId : $scope.organizationId,
                    unitId : $scope.unitId
                };
                 var list = [];
                var URI = BASE_URL + ROOT_URL
                        + GETDOCTORFAVOURITEMEDICATIONFORCOVERSHEET;

                GenericServiceParamHeader
                .serviceAction(METHOD_POST, URI, data,
                        NOTIFICATION_MSG_STATUS_FALSE)
                .then(function(response) {
                    if (response.data.status == "success") {
                        list = response.data.listObject;
                        $scope.favouriteMedicationsFromMaster=[];
                        $.each(list, function (i, e) {
                            var matchingItems = $.grep($scope.favouriteMedicationsFromMaster, function (item) {
                               var count = item.itemName === e.itemName && item.genericName === e.genericName;
                                if(count){
                                    if(item.doctorFavoriteId != undefined && item.doctorFavoriteId != null && item.doctorFavoriteId != 0){
                                        e = item;
                                    }
                                }
                               return count;
                            });
                            if (matchingItems.length === 0){
                                $scope.favouriteMedicationsFromMaster.push(e);
                            }
                        });

                        if($scope.medicationDetails.length>0){
                            $.each($scope.favouriteMedicationsFromMaster, function (i, e) {
                                var matchingItems = $.grep($scope.medicationDetails, function (item) {
                                   var count = item.itemName === e.itemName && item.genericName === e.genericName;
                                    if(count){
                                        if(item.favouriteMedicationId != undefined && item.favouriteMedicationId != null && item.favouriteMedicationId != 0){
                                            item.doctorFavoriteId = undefined;
                                            item.favouriteMedicationId = 0;
                                        }
                                    }
                                });
                            });
                        }

                        angular.forEach($scope.favouriteMedicationsFromMaster, function(value){
                            if(value.doctorFavoriteId === undefined || value.doctorFavoriteId === null || value.doctorFavoriteId === 0){
                                value.doctorFavoriteId = value.favouriteMedicationId;
                            }
                        });
                        $rootScope.stopLoader();
                    }
                    else{
                        $rootScope.stopLoader();
                        growl.warning('Unable to Get Favourite Medications..!');
                    }
                });
            }

        $scope.customFilter = function(searchText) {
            return function(item) {
                if (!searchText) return true; // Show all if search text is
												// empty
                searchText = searchText.toLowerCase();
                return item.itemName.toLowerCase().includes(searchText) || item.genericName.toLowerCase().includes(searchText);
            };
        };

