			$scope.getColor = function(apacheScore, mewsScore, gcsScore, sofaScore) {
		        function ApacheScoreColor(lower, higher) {
			        if (lower >= 0 && higher <= 10) return 1; 
			        if (lower >= 11 && higher <= 20) return 2; 
			        if (lower >= 21 && higher <= 30) return 3; 
			        if (lower >= 31) return 4;
			        return -1;
			    }
			    function MEWSScoreColor(lower, higher) {
	                if (lower >= 0 && higher <= 4 && $scope.patientDetails.IsScoreWith3==false) return 1;
	                if (lower >= 0 && higher <= 4 && $scope.patientDetails.IsScoreWith3==true) return 2; 
	          		if (lower >= 5 && higher <= 6) return 3;
	          		if (lower >= 7) return 4;
	          		return -1;
			    }
			    function SOFAScoreColor(lower, higher) {
			        if (lower >= 0 && higher <= 9) return 1; 
			        if (lower >= 10 && higher <= 12) return 2;
			        if (lower >= 13 && higher <= 15) return 3; 
			        if (lower >= 16) return 4; 
			        return -1; 
			    }
			    function GCSScoreColor(lower, higher) {
			        if (lower >= 13 && higher <= 15) return 1; 
			        if (lower >= 9 && higher <= 12) return 2; 
			        if (lower >= 5 && higher <= 8) return 3; 
			        if (lower >= 3 && higher <= 4) return 4; 
			        return -1; 
			    }
			    const scores = [
			        ApacheScoreColor(apacheScore, apacheScore), 
			        MEWSScoreColor(mewsScore, mewsScore), 
			        SOFAScoreColor(sofaScore, sofaScore),
			        GCSScoreColor(gcsScore, gcsScore) 
			    ];

			    const maxColorCode = Math.max(...scores);

			    switch (maxColorCode) {
			        case 1: return "#0cac26";
			        case 2: return "#FFB800";
			        case 3: return "#F8CBAD";
			        case 4: return "#d11b1b";
			        default: return "#d11b1b"; 
			    }
			};

					
