// Calculate total dynamically
$scope.calculateGCSTotal = function () {
  var e = parseInt($scope.gcs.eye) || 0;
  var v = parseInt($scope.gcs.verbal) || 0;
  var m = parseInt($scope.gcs.motor) || 0;

  $scope.gcs.total = e + v + m;
};

// Save GCS to ABCDE
$scope.saveGCS = function () {
  $scope.abcde.disability.gcsTotal = $scope.gcs.total;
  $('#gcsModal').modal('hide');
};



