									// for comparing the vital min and max range
        $scope.checkCriticalIdentificationRangeForABCDE = function(vitalFinalList){

            if(vitalFinalList.maxValue != null || vitalFinalList.minValue != null){

                if(vitalFinalList.maxValue == null){
                    vitalFinalList.maxValue = 0;
                }else if(vitalFinalList.minValue == null){
                    vitalFinalList.minValue = 0;
                }else if(vitalFinalList.vitalValue == ""){
                    growl.warning(vitalFinalList.vitalName + " should be greater than " + vitalFinalList.minValue + "");
                }

                var max = Number(vitalFinalList.maxValue);
                var min = Number(vitalFinalList.minValue);
                var vitalVal = Number(vitalFinalList.vitalValue);

                if(max < vitalVal){
                    growl.warning(vitalFinalList.vitalName + " should be less than " + max + "");
                    vitalFinalList.vitalValue = "";
                }else if(min > vitalVal){
                    growl.warning(vitalFinalList.vitalName + " should be greater than " + min + "");
                    vitalFinalList.vitalValue = "";
                }
            }

            if(vitalFinalList.vitalId !==undefined && vitalFinalList.vitalId === 10 && vitalFinalList.vitalValue !== undefined && vitalFinalList.vitalValue !== null && vitalFinalList.vitalValue !== ''){
//                for Respiration
                $scope.abcde.breathing.rr = vitalFinalList.value;
            }
            else if(vitalFinalList.vitalId !==undefined && vitalFinalList.vitalId === 14 && vitalFinalList.vitalValue !== undefined && vitalFinalList.vitalValue !== null && vitalFinalList.vitalValue !== ''){
//                for SpO2
                $scope.abcde.breathing.spo2 = vitalFinalList.value;
            }
            else if(vitalFinalList.vitalId !==undefined && vitalFinalList.vitalId === 19 && vitalFinalList.vitalValue !== undefined && vitalFinalList.vitalValue !== null && vitalFinalList.vitalValue !== ''){
//                for Bp Systolic
                $scope.abcde.circulation.bpSys = vitalFinalList.value;
            }
            else if(vitalFinalList.vitalId !==undefined && vitalFinalList.vitalId === 20 && vitalFinalList.vitalValue !== undefined && vitalFinalList.vitalValue !== null && vitalFinalList.vitalValue !== ''){
//                for Bp Diastolic
                $scope.abcde.circulation.bpDia = vitalFinalList.value;
            }
            else if(vitalFinalList.vitalId !==undefined && vitalFinalList.vitalId === 4 && vitalFinalList.vitalValue !== undefined && vitalFinalList.vitalValue !== null && vitalFinalList.vitalValue !== ''){
//                for HeartRate
                $scope.abcde.circulation.hr = vitalFinalList.value;
            }
            else if(vitalFinalList.vitalId !==undefined && vitalFinalList.vitalId === 5 && vitalFinalList.vitalValue !== undefined && vitalFinalList.vitalValue !== null && vitalFinalList.vitalValue !== ''){
//                for Blood Sugar(Glucose)
                $scope.abcde.disability.glucose = vitalFinalList.value;
            }
            else if(vitalFinalList.vitalId !==undefined && vitalFinalList.vitalId === 6 && vitalFinalList.vitalValue !== undefined && vitalFinalList.vitalValue !== null && vitalFinalList.vitalValue !== ''){
//                for Temperature
                $scope.abcde.exposure.temperature = vitalFinalList.value;
            }
        }

        $scope.filterVitalList = function(){
            $scope.primaryExaminationBreathingVitalList = [];
            $scope.primaryExaminationCirculationVitalList = [];
            $scope.primaryExaminationInterventionVitalList = [];
            $scope.primaryExaminationDisabilityVitalList = [];
            $scope.primaryExaminationPupilsVitalList = [];


            angular.forEach(vitalFinalList, function(vital) {
                if(vital.vitalId !== undefined && vital.vitalId !== null && vital.vitalId > 0)
                {
                    if(vital.vitalId == 10 || vital.vitalId == 14 || vital.vitalId == 14){
                        $scope.primaryExaminationVitalList.push(vital);
                    }
                }
            });

        }

